from pathlib import Path
from datetime import datetime,timezone,timedelta
import json,html,hashlib,zipfile,os,shutil
R=Path(__file__).resolve().parents[1]
E=R/'evidence'
load=lambda p:json.loads((R/p).read_text())
core=load('tests/legacy_rerun/results/core_results.json')
gen=load('tests/legacy_rerun/results/generation_results.json')
dom=load('evidence/integration_results.json')
assert len(core)==356 and len(gen)==504 and len(dom)==147
assert all(c['status']=='PASS' for c in core+gen+dom),'Unresolved test case'
old=load('evidence/originals_integrity.json');assert old['unchanged']==650
stamp=datetime.now(timezone(timedelta(hours=8))).isoformat(timespec='seconds')
css='''*{box-sizing:border-box}body{margin:0;color:#233b37;background:#f6f4ec;font:17px/1.75 system-ui,"Microsoft JhengHei",sans-serif}main{max-width:1120px;padding:48px 26px 72px;margin:auto}h1{font-size:clamp(30px,5vw,46px);line-height:1.3;letter-spacing:-.025em}h2{font-size:25px;margin:38px 0 15px}h3{font-size:19px}.kicker{letter-spacing:.12em;font-size:13px;color:#567168;font-weight:750}.card{border:1px solid #d7dfd3;border-radius:20px;padding:24px;background:#fffef9;margin:18px 0}.note{padding:18px 21px;background:#f6e7cd;border-left:4px solid #b17b32;border-radius:0 15px 15px 0;margin:22px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.stats div{background:#e8eee4;border-radius:18px;padding:22px}.stats strong{display:block;font-size:29px}.muted,small{color:#637169}a{color:#24564c}a.button,button{display:inline-block;background:#24564c;color:#fff;padding:13px 21px;border-radius:13px;border:0;font:700 17px system-ui;text-decoration:none;cursor:pointer}a.secondary{background:#fffdf6;color:#24564c;border:1px solid #97ad9e}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}table{width:100%;border-collapse:collapse;font-size:15px}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dbe1d5;padding:14px 10px}th{background:#eaf0e6}.scroll{overflow:auto}code{font-size:14px;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#edf0e7;padding:18px;border-radius:12px;font-size:14px}img{width:100%;border-radius:15px;border:1px solid #dbe1d5}figure{margin:0}figcaption{color:#637169;font-size:14px}input,select{max-width:100%;padding:12px;font:inherit;border:1px solid #97ad9e;border-radius:10px}details{margin:16px 0}summary{font-weight:750;cursor:pointer}.small{font-size:14px}@media(max-width:680px){main{padding:26px 18px 48px}.grid{grid-template-columns:1fr}.stats{grid-template-columns:1fr}.card{padding:19px}a.button{width:100%;text-align:center}td,th{padding:11px 8px}}'''
def page(title,body):return '<!doctype html><html lang="zh-HK"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+css+'</style></head><body><main>'+body+'</main></body></html>'
start='''<div class="kicker">WORDQUEST · INTEGRATION R1</div><h1>英文與數學，<br>在同一個程式學習。</h1><p>已套用可完整讀取的英文 <b>V32</b> 與數學 <b>0.1.2</b>。孩子、金幣及家長驗證共用；普通數學與奧數進度分開保存。</p><div class="actions"><a class="button" href="app/index.html">開啟英文＋數學整合版</a><a class="button secondary" href="docs/本輪套用及驗證報告.html">查看套用及測試報告</a></div><div class="note"><b>先解壓整個 ZIP，再開啟。</b><br>一般開啟本頁及程式不需要 Python。Windows 可另用 <code>START_WINDOWS.cmd</code> 建立本機網址；啟動器未經本輪 Windows 真機驗證。請固定使用同一網址與瀏覽器。</div><div class="grid"><section class="card"><h2 style="margin-top:0">已有舊資料</h2><p>先在舊英文及舊數學頁面分別匯出備份。換瀏覽器、網址、<code>file://</code> 或本機伺服器，都不保證自動帶入原資料。</p><p>不同孩子擁有者的數學備份會被拒絕；本版不自動猜測孩子配對。</p></section><section class="card"><h2 style="margin-top:0">本版邊界</h2><p>不是 V33 或 Maths 0.1.3。未取得較新 ZIP 原件或新角色原圖；角色沿用 V32 原有素材。</p><p>數學：23 個普通數學入門技能、5 個奧數主題、84 個模板；不是小一至小六全課程。</p></section></div><h2>資料與說明</h2><div class="card"><p><a href="README_先看這份.md">使用、備份及版本說明</a>　·　<a href="docs/開發交接_R1.md">R1 開發交接</a></p><p><a href="originals/WordQuest_Program_and_Data_20260929/START_HERE.html">開啟原有資料包入口（650 個原檔保留）</a></p><p><a href="originals/WordQuest_Program_and_Data_20260929/04_Assets/素材索引.html">舊版素材瀏覽</a>　·　<a href="PACKAGE_MANIFEST.json">完整檔案清單</a></p></div><p class="muted small">本包包含程式、題庫、素材、原始碼及審核資料，不包含你個人電腦瀏覽器內尚未匯出的學員紀錄。</p>'''
(R/'START_HERE.html').write_text(page('WordQuest｜英文＋數學整合 R1',start))
rows=''.join(f'<tr><td>{html.escape(x)}</td><td>{html.escape(y)}</td><td>{html.escape(z)}</td></tr>' for x,y,z in [
 ('英文','V32','完整 HTML／原始碼／內嵌素材取自上一個資料包；原功能保留。'),
 ('數學／奧數','0.1.2','從已取回的整合器有效載荷套入同一 HTML；不是 0.1.3。'),
 ('角色','V32 原有角色','原圖與原身份沿用，按畫面／回饋顯示；不影響判分。'),
 ('本輪新增','V32-M0.1.2-R1','帳戶橋接、共用金幣、家長驗證、課堂恢復及鍵盤焦點等修正。')])
body=f'''<div class="kicker">WORDQUEST · VERSION APPLICATION &amp; VERIFICATION</div><h1>較舊可用版本，<br>已實際接入同一頁面。</h1><p>建立記錄：{html.escape(stamp)}（香港時間）。基礎為英文 V32＋Maths 0.1.2，本輪新增標記 <b>整合 R1</b>。</p><div class="actions"><a class="button" href="../app/index.html">開啟整合程式</a><a class="button secondary" href="../START_HERE.html">返回入口</a></div><div class="stats"><div><strong>1,007 / 1,007</strong>本輪案例通過</div><div><strong>147</strong>整合／真實 DOM／故障／視窗案例</div><div><strong>650 / 650</strong>舊資料檔原样保留</div></div><div class="note"><b>通過不代表完美或已達商用。</b>本輪 DOM 實測使用真正 Chromium 的點擊、填答及鍵盤，但透過 <code>page.set_content()</code> 載入完整 HTML；儲存、Web Locks、WebCrypto 介面使用隔離測試轉接器。沒有把原生保存、跨分頁鎖、Windows 啟動或手機真機列作已驗證。</div><h2>一、套用的實際版本</h2><div class="scroll"><table><thead><tr><th>組件</th><th>版本</th><th>已套用範圍</th></tr></thead><tbody>{rows}</tbody></table></div><p>本輪再次嘗試 V33、0.1.3 及較舊 ZIP 的原始檔取回，都回報沒有獲授權的原始位元組路徑。因此改用上一個可完整開啟資料包中的 V32 與 0.1.2，不以檔名紀錄冒充已取回的新程式。較新檔案仍需將來取得原件後另行比對。</p><h2>二、這次實際修改</h2><div class="card"><h3>帳戶、孩子及金幣</h3><p>在英文封閉作用域內注入專用橋接，數學使用當前英文孩子，停止產生第二套獨立名單。合資格課堂使用英文原有任務錢包規則，保存失敗不完成結算；重複同步不再次派幣。</p><h3>家長權限與科目進度</h3><p>英文家長頁顯示數學摘要；數學設定、備份及完成頁的進度入口沿用英文家長驗證。普通數學及奧數保留獨立作答及掌握度資料。</p><h3>課堂、草稿與刪除資料</h3><p>拒絕缺少题目的續課資料；同頁訪客草稿可關閉後恢復。儲存失敗退出前提示；鍵盤提交後聚焦回饋。英文刪除孩子時清理該孩子的數學主資料及還原前副本，清理失敗則取消保存。</p><h3>舊版角色接入</h3><p>沿用 V32 原有圖像及身份，按學習畫面及回饋展示。未重新生成新版六張原圖，也不宣稱恢复 0.1.3 完整角色功能。</p></div><h2>三、實際驗證結果</h2><div class="scroll"><table><thead><tr><th>分組</th><th>案例</th><th>通過</th><th>內容</th></tr></thead><tbody><tr><td>數學核心</td><td>356</td><td>356</td><td>判分84、解析80、狀態96、學習56、保存40。</td></tr><tr><td>獨立答案核對</td><td>504</td><td>504</td><td>84模板 × 6種子；獨立 Python 有理數／枚舉求解，不是程式自己判自己。</td></tr><tr><td>真實 DOM 題目</td><td>84</td><td>84</td><td>每模板注入一題已標示的測試夾具，真正顯示、填答、提交、核對回饋焦點。</td></tr><tr><td>整合流程</td><td>36</td><td>36</td><td>註冊、共用孩子、十題練習、兩種完整六階段課堂、家長、換孩子、角色及刪除。</td></tr><tr><td>隔離故障注入</td><td>15</td><td>15</td><td>過期寫入、錯誤擁有者、結算／ACK故障、限額、恢復及資料清理等。</td></tr><tr><td>視窗寬度</td><td>12</td><td>12</td><td>1280、768、390、320像素；首頁、目錄及題面可見性／水平溢出。</td></tr><tr><th>本輪合計</th><th>1,007</th><th>1,007</th><th>案例數不是獨立功能數或軟件評分。</th></tr></tbody></table></div><p>另外 <b>35 段交付 JavaScript</b> 經 Node 語法檢查全部通過，不混入上述 1,007 個功能／測試案例。原有 650 檔與上一個 ZIP 逐檔 SHA-256 比對相同。</p><p>初次新測試腳本曾出現選擇器重複、把 export() 物件當 JSON 字串及測試算式多加乘一等夾具錯誤，修正測試後重跑；沒有把這些腳本錯誤當成產品漏洞。原有課堂 queue／名單恢復及回饋焦點問題則在產品補丁中修正。發展中的結果與最終結果分開保留。</p><h2>四、實際畫面</h2><figure><img src="../evidence/english-home-1280.png" alt="英文首頁新增普通數學與奧數入口"><figcaption>桌面：英文首頁保留，新增兩科入口及共用帳戶說明。</figcaption></figure><div class="grid" style="margin-top:22px"><figure><img src="../evidence/maths-home-390.png" alt="390像素數學首頁沿用舊版角色"><figcaption>390像素視窗：數學主頁與舊版角色。</figcaption></figure><figure><img src="../evidence/maths-answer-390.png" alt="390像素真正數學填答欄和提交按鈕"><figcaption>題面內捲動後的答案欄；部分題目仍需垂直捲動，不宣稱所有手機單屏完成。</figcaption></figure></div><h2>五、未完成及未驗證</h2><div class="note">未取回英文 V33 原創街機、Maths 0.1.3 新角色套件；數學仍非全小學課程。兩份科目備份尚未合成單一備份，也未自動配對舊獨立數學學員。原生瀏覽器保存／重新啟動、多分頁 Web Locks、Safari／iPhone／Android、Windows 啟動器、外部 OCR／CDN 及真人語音沒有通過本輪驗收。英文所有舊遊戲及英文題型亦未逐一全面重跑。</div><p>本機跨 key 的刪除／回復不是資料庫原子交易；突然關機仍有風險。正式商用需要持久層交易、原生真機測試與教師／學生試用。請在測試帳戶驗收，先備份舊版資料。</p><h2>六、逐項查閱</h2><div class="actions"><input id="search" placeholder="搜尋案例、模板或功能"><select id="group"><option value="">全部分組</option></select></div><p id="count" class="muted"></p><div class="scroll"><table><thead><tr><th>編號／分組</th><th>案例</th><th>結果</th></tr></thead><tbody id="casebody"></tbody></table></div><div class="actions"><button id="prev">上一頁</button><button id="next">下一頁</button></div><h2>七、原始證據與程式</h2><p><a href="../evidence/integration_results.json">本輪整合逐項結果</a> · <a href="../tests/legacy_rerun/results/core_results.json">核心356項</a> · <a href="../tests/legacy_rerun/results/generation_results.json">獨立驗算504項</a> · <a href="../evidence/environment.json">環境及替身說明</a> · <a href="../evidence/originals_integrity.json">原檔完整性</a></p><p><a href="開發交接_R1.md">開發交接與重跑指令</a> · <a href="../README_先看這份.md">使用及備份說明</a> · <a href="../originals/WordQuest_Program_and_Data_20260929/START_HERE.html">原資料包入口</a></p>'''
cases=[{'id':c['id'],'group':c.get('category',c.get('group','')),'name':c['name'],'status':c['status']} for c in core+gen+dom]
j=json.dumps(cases,ensure_ascii=False).replace('<','\\u003c')
script='''<script>const cases=__CASES__;let page=0;const q=document.getElementById('search'),g=document.getElementById('group');for(const x of [...new Set(cases.map(c=>c.group))]){let o=document.createElement('option');o.value=x;o.textContent=x;g.append(o)}function draw(){const list=cases.filter(c=>(!g.value||c.group===g.value)&&JSON.stringify(c).toLowerCase().includes(q.value.toLowerCase()));page=Math.min(page,Math.max(0,Math.ceil(list.length/50)-1));const b=document.getElementById('casebody');b.replaceChildren();for(const c of list.slice(page*50,page*50+50)){const r=document.createElement('tr');for(const s of [c.id+' · '+c.group,c.name,c.status==='PASS'?'通過':'未通過']){let t=document.createElement('td');t.textContent=s;r.append(t)}b.append(r)}document.getElementById('count').textContent=list.length+' 項 · 第 '+(page+1)+' / '+Math.max(1,Math.ceil(list.length/50))+' 頁';document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=(page+1)*50>=list.length}q.oninput=g.onchange=()=>{page=0;draw()};document.getElementById('prev').onclick=()=>{page--;draw()};document.getElementById('next').onclick=()=>{page++;draw()};draw();</script>'''.replace('__CASES__',j)
# Normalize accidental simplified characters in new documentation only.
for a,b in [('原样','原樣'),('缺少题目','缺少題目'),('恢复','恢復')]:body=body.replace(a,b)
(R/'docs/本輪套用及驗證報告.html').write_text(page('WordQuest R1｜套用及1007項驗證',body+script))
(E/'final_summary.json').write_text(json.dumps({'build':'V32-M0.1.2-R1','created_hkt':stamp,'core':{'total':356,'pass':356},'independent_oracle':{'total':504,'pass':504},'integration_DOM_fault_viewport':{'total':147,'pass':147},'total_cases':1007,'pass':1007,'fail':0,'js_syntax_scripts':35,'original_files_preserved_unchanged':650,'native_browser_persistence_verified':False,'windows_launcher_verified':False,'student_data':'No real student records; all new tests use isolated fixtures.'},ensure_ascii=False,indent=2))
# Preserve development failures without presenting them as final run output.
if (E/'integration_fatal.txt').exists():(E/'integration_fatal.txt').rename(E/'development-test-harness-fatal.txt')
for f in R.rglob('__pycache__'):shutil.rmtree(f)
print('Created START_HERE and final HTML report with',len(cases),'case rows')
